for dct, d, foot, bench in ((BK, "work/buck/b10", FOOT_B, BENCH_B), (RC, "work/rocco/r10", FOOT_R, BENCH_R)):
    for k, (title, body, src, tags) in dct.items():
        open(f"{ROOT}/{d}/{k}_desc.txt", "w").write(f"{body}\n\nSources: {src}{foot}\n\n{tags}\n")
        sp = json.load(open(f"{ROOT}/{d}/{k}.json")); sc = []
        KM = {"counter": "stat", "pixel": "stat", "bars": "chart", "line": "chart", "scale": "chart", "versus": "vs", "phone": "phone", "call": "phone",
              "kinetic": "sticker", "stamp": "sticker", "flagvote": "sticker", "quiz": "sticker", "flags": "sticker", "store": "sticker", "receipt": "stat",
              "grid": "stat", "spend": "stat", "chalk": "chart"}
        for i, (_, t) in enumerate(sp["lines"]):
            main = next((x for x in sp["shots"] if x.get("line") == i and not x.get("_auto") and x["kind"] != "end"), None) or next((x for x in sp["shots"] if "line" not in x), {"kind": "host"})
            if d.endswith("b10"): vis = str(main.get("bg", "")).endswith(".mp4") and (main["kind"] in ("host", "kinetic", "versus", "stamp") or (main["kind"] == "counter" and main.get("dim", 90) <= 100))  # footage is the picture; counters/bars/quizzes over footage are graphics
            else: vis = bool(main.get("bg")) and main.get("dim", 0) <= 100 and main["kind"] != "chalk"  # Rocco: a character scene on a visible 3D set
            kk = "broll" if vis else KM.get(main["kind"], "broll"); tx = re.sub(r"\[[^\]]*\]\s*", "", t).strip()
            sc.append({"text": tx, kk: f"{k}-{i}"} if kk != "broll" else {"text": tx, "shots": [{"broll": main.get("bg") or main.get("set", "set")}]})
        sc.append({"text": ""})
